//! Detached Attr factories retain genuine owner and document-specific case.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn inert_template_import_deep_shallow_nested_contents_use_destination_owners_and_new_identities(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var source=document.createElement('template');source.innerHTML='<span data-note="old">top</span><template id="inner"><b>nested</b></template>';var content=source.content,inner=content.lastChild,innerContent=inner.content,sourceOwner=content.ownerDocument,html=document.implementation.createHTMLDocument('target'),xml=document.implementation.createDocument(null,''),marker=document.createElement('template').content.ownerDocument;for(var target of [html,xml,marker]){var copy=target.importNode(source,true),cloned=copy.content,owner=cloned.ownerDocument,nested=cloned.lastChild;if(copy===source||!(copy instanceof HTMLTemplateElement)||copy.ownerDocument!==target||copy.parentNode!==null||copy.childNodes.length||cloned===content||cloned.parentNode!==null||cloned!==copy.content||owner.defaultView!==null||owner.contentType!=='application/xml'||cloned.firstChild===content.firstChild||cloned.firstChild.ownerDocument!==owner||cloned.firstChild.getAttributeNode('data-note').ownerDocument!==owner||nested===inner||nested.ownerDocument!==owner||nested.content===innerContent||nested.content.ownerDocument!==owner||nested.content.textContent!=='nested')throw 'actual target template host/content and nested owner identities';if(target===marker?owner!==target:owner===target)throw 'appropriate owner versus ordinary target';var sibling=target.createElementNS('http://www.w3.org/1999/xhtml','template');if(sibling.content.ownerDocument!==owner)throw 'one cached destination owner';var shallow=target.importNode(source,false);if(shallow.content===cloned||shallow.content.ownerDocument!==owner||shallow.content.childNodes.length)throw 'genuine shallow empty template contents';cloned.firstChild.setAttribute('data-note','copy');nested.content.firstChild.textContent='copy';if(content.firstChild.getAttribute('data-note')!=='old'||innerContent.textContent!=='nested'||source.content!==content||content.ownerDocument!==sourceOwner)throw 'source template graph never changed';}
"#);
}
#[test]
fn inert_template_import_target_kind_not_source_kind_controls_content_document_factories(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var ns='http://www.w3.org/1999/xhtml',xml=document.implementation.createDocument(null,''),source=xml.createElementNS(ns,'template'),owner=source.content.ownerDocument,element=owner.createElement('MiXeD');element.appendChild(owner.createCDATASection('\ud800'));source.content.appendChild(element);var html=document.implementation.createHTMLDocument('target'),copy=html.importNode(source,true),targetOwner=copy.content.ownerDocument,node=copy.content.firstChild;if(targetOwner===owner||targetOwner===html||targetOwner.createAttribute('MiXeD').name!=='mixed'||owner.createAttribute('MiXeD').name!=='MiXeD'||node.namespaceURI!==null||node.localName!=='MiXeD'||node.ownerDocument!==targetOwner||node.firstChild.nodeType!==4||node.firstChild.ownerDocument!==targetOwner||node.firstChild.data.charCodeAt(0)!==0xd800)throw 'actual source data and destination HTML owner kind';var caught=false;try{targetOwner.createCDATASection('x');}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught)throw 'imported CData does not change target factory kind';var htmlSource=document.createElement('template');htmlSource.innerHTML='<span data-note="held">source</span>';var xmlCopy=xml.importNode(htmlSource,true),xmlOwner=xmlCopy.content.ownerDocument;if(xmlOwner.createAttribute('MiXeD').name!=='MiXeD'||xmlCopy.content.firstChild.tagName!=='span'||xmlOwner.createElement('MiXeD').namespaceURI!==null)throw 'XML destination associated owner does not inherit source HTML flag';
"#);
}
#[test]
fn inert_template_import_loaded_source_lazy_contents_and_dictionary_reentry_are_real(){
 let mut doc=crate::html::parse_loaded_document("<html><body><template id=source><span>loaded</span><template><b>nested</b></template></template></body></html>",&||Ok(())).unwrap();doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);run(&mut doc,&mut forms,&mut page,r#"
var source=document.getElementById('source'),target=document.implementation.createHTMLDocument('target'),calls=0,copy=target.importNode(source,{get selfOnly(){calls++;return false;}});if(calls!==1||copy.childNodes.length||copy.content.childNodes.length!==2||copy.content.firstChild.textContent!=='loaded'||copy.content.lastChild.content.textContent!=='nested'||copy.content.firstChild===source.content.firstChild||copy.content.ownerDocument===source.content.ownerDocument)throw 'native loaded template backing stays content, not DOM children';var caught=false;try{target.importNode(source,{get selfOnly(){source.content.appendChild(source.content.ownerDocument.createElement('input'));return false;}});}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||copy.content.childNodes.length!==2||target.body.childNodes.length)throw 'actual postdictionary protected descendants refuse without modifying earlier copies';
"#);
}

#[test]
fn inert_template_import_ordinary_dom_children_and_native_content_ignore_author_getter(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var sourceDoc=document.implementation.createHTMLDocument('source'),source=sourceDoc.createElement('template'),ordinary=sourceDoc.createElement('em');ordinary.textContent='ordinary';source.appendChild(ordinary);var actual=source.content;if(actual.childNodes.length||source.firstChild!==ordinary)throw 'DOM host children are not template contents';actual.appendChild(actual.ownerDocument.createTextNode('content'));var reads=0;Object.defineProperty(source,'content',{configurable:true,get:function(){reads++;throw 'author content getter';}});var target=document.implementation.createHTMLDocument('target'),copy=target.importNode(source,true);if(reads||copy.childNodes.length!==1||copy.firstChild===ordinary||copy.firstChild.ownerDocument!==target||copy.firstChild.textContent!=='ordinary'||copy.content.textContent!=='content'||copy.content.ownerDocument===target||actual.textContent!=='content'||source.firstChild!==ordinary)throw 'actual host children and native contents copied separately';
"#);
}

#[test]
fn inert_template_import_saved_child_origin_precedes_dictionary_and_source_cache_work(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var target=document.implementation.createDocument(null,''),source=document.createElement('template');source.innerHTML='<span>held</span>';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Document.prototype.importNode,calls=0,options={get selfOnly(){calls++;return false;}},copy=saved.call(target,source,options),owner=copy.content.ownerDocument;if(copy===source||copy.ownerDocument!==target||copy.content.textContent!=='held'||owner.createAttribute('MiXeD').name!=='MiXeD'||calls!==1)throw 'genuine child realm template import';
"#);page.set_location(&crate::navigation::address("https://other-template-import.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(target,source,options);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==1||copy.content.ownerDocument!==owner||copy.content.textContent!=='held'||source.content.textContent!=='held')throw 'origin before template options or copies';");
}
